from pathlib import Path
from pydantic import BaseModel, field_validator

# --- 1. Template: prompts live in files, not f-strings -----------
TRIAGE_PROMPT = Path("prompts/triage_v3.txt").read_text(encoding="utf-8")

class TriageInput(BaseModel):
    ticket: str
    @field_validator("ticket")
    @classmethod
    def cap_length(cls, v: str) -> str:
        if len(v) > 4_000: raise ValueError("ticket too long")
        return v

def render(inp: TriageInput) -> str:
    return TRIAGE_PROMPT.replace("{ticket}", inp.ticket)

# --- 2. Versioning: log with every call ---------------------------
PROMPT_VERSION = "triage_v3"   # bump on every change; log alongside usage

# --- 3. Eval harness: golden set + regression gate ----------------
GOLDEN = [
    {"ticket": "charged twice", "expect": "P1"},
    {"ticket": "love the app!", "expect": "P3"},
]

def score(prompt_text: str) -> float:
    ok = 0
    for ex in GOLDEN:
        out = call_llm(prompt_text.replace("{ticket}", ex["ticket"]))
        ok += ex["expect"] in out
    return ok / len(GOLDEN)

# CI gate:  assert score(NEW) >= score(MAIN) - 0.02

